.custombuild-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2733;
    background: linear-gradient(160deg, #f6f2ea 0%, #efe7da 100%);
    border-radius: 18px;
}

.custombuild-container * {
    box-sizing: border-box;
}

.custombuild-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14213d 0%, #1f3a5f 55%, #2c4f7c 100%);
    color: #f4f0e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 33, 61, 0.32);
    border-bottom: 4px solid #c79a3f;
}

.custombuild-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.custombuild-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8c878;
    background: rgba(199, 154, 63, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.custombuild-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6ddcd;
}

.custombuild-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e54;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.custombuild-period-counter #currentDay,
.custombuild-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.custombuild-round-name {
    background: #e6dcc6;
    color: #5a4413;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.custombuild-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c3a1c;
    background: #f6e0d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.custombuild-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.custombuild-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dac8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
    border-top: 4px solid #2c4f7c;
}

.custombuild-card-needs { border-top-color: #1f6f54; }
.custombuild-card-impact { border-top-color: #2c5fb0; }
.custombuild-card-margin { border-top-color: #c79a3f; }
.custombuild-card-feasibility { border-top-color: #7a4fb0; }

.custombuild-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7585;
}

.custombuild-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.custombuild-card-needs .custombuild-value { color: #1f6f54; }
.custombuild-card-impact .custombuild-value { color: #2c5fb0; }
.custombuild-card-margin .custombuild-value { color: #b07f18; }
.custombuild-card-feasibility .custombuild-value { color: #7a4fb0; }

.custombuild-sublabel {
    font-size: 0.76rem;
    color: #7d8694;
    line-height: 1.35;
}

.custombuild-margin-below .custombuild-value { color: #c0392b; }
.custombuild-margin-floor .custombuild-value { color: #1f6f54; }

.custombuild-budget-over { border-top-color: #c0392b; }
.custombuild-budget-over .custombuild-value { color: #c0392b; }

.custombuild-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #f1ead9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c79a3f;
}

.custombuild-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8c878;
}

.custombuild-budget-bar.custombuild-budget-broken #budgetDisplay {
    color: #ff8a6f;
}

.custombuild-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c79a3f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
}

.custombuild-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.custombuild-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.custombuild-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34404f;
}

.custombuild-briefing-text strong { color: #1f6f54; }
.custombuild-briefing-text em { color: #9c3a1c; font-style: italic; }

.custombuild-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dac8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.custombuild-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #efe7da;
    padding-bottom: 8px;
}

.custombuild-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283648;
    margin: 14px 0 6px;
}

.custombuild-container select,
.custombuild-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3c8af;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f1;
    color: #1f2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.custombuild-container select:focus,
.custombuild-container input[type="number"]:focus {
    outline: none;
    border-color: #c79a3f;
    box-shadow: 0 0 0 3px rgba(199, 154, 63, 0.18);
}

.custombuild-container select option {
    background-color: #ffffff;
    color: #1f2733;
}

.custombuild-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3f;
}

.custombuild-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f3a5f;
    margin-top: 4px;
}

.custombuild-range-readout span:last-child {
    color: #b07f18;
    font-weight: 800;
}

.custombuild-hint {
    font-size: 0.8rem;
    color: #7d8694;
    margin-top: 4px;
    line-height: 1.4;
}

.custombuild-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.custombuild-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #2c4f7c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fdf8ec;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.28);
}

.custombuild-container .btn-primary:hover {
    filter: brightness(1.12);
}

.custombuild-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3c8af;
    color: #6c7585;
}

.custombuild-coach {
    background: #14213d;
    color: #eee6d5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 4px solid #c79a3f;
}

.custombuild-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8c878;
    margin-bottom: 8px;
}

.custombuild-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.custombuild-coach-body strong { color: #f0cf86; }
.custombuild-coach-body em { color: #ffb59a; font-style: italic; }

.custombuild-history,
.custombuild-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dac8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.custombuild-history h3,
.custombuild-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.custombuild-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283648;
}

.custombuild-container table#usfHistoryTable th {
    background: #f2ecde;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d5bd;
}

.custombuild-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece2;
}

.custombuild-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7ef;
}

.custombuild-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .custombuild-container {
        padding: 14px;
    }
    .custombuild-header h1 {
        font-size: 1.7rem;
    }
    .custombuild-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .custombuild-value {
        font-size: 2rem;
    }
    .custombuild-clock {
        margin-left: 0;
    }
    .custombuild-period-counter {
        font-size: 0.88rem;
    }
    .custombuild-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .custombuild-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion debrief — self-contained, append-only. Custom Build (exec-ed bid) palette. */
.cbsim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2233; text-align: center; padding: 4px 2px 8px; }
.cbsim-cm-title { font-size: 20px; font-weight: 700; color: #14213d; margin-bottom: 14px; }
.cbsim-cm-scorewrap { background: linear-gradient(135deg, #14213d 0%, #1f3a5f 55%, #2c4f7c 100%); color: #ffffff; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.cbsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #e8c878; }
.cbsim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.9; color: #ffffff; }
.cbsim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; color: #ffffff; }
.cbsim-cm-badges { margin-top: 10px; }
.cbsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.cbsim-cm-badge-ok { background: #d6e8de; color: #1f6f54; }
.cbsim-cm-badge-miss { background: #f6dcd2; color: #9a2f17; }
.cbsim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 520px; }
.cbsim-cm-kpi { flex: 1 1 110px; min-width: 110px; background: #f6f2ea; border: 1px solid #e3dac8; border-radius: 10px; padding: 10px 6px; }
.cbsim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #14213d; }
.cbsim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #5a6070; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.cbsim-cm-insights { text-align: left; max-width: 540px; margin: 0 auto; background: #faf7f0; border-left: 4px solid #c79a3f; border-radius: 8px; padding: 12px 16px; }
.cbsim-cm-ins-h { font-weight: 700; color: #14213d; margin-bottom: 6px; font-size: 14px; }
.cbsim-cm-insights ul { margin: 0; padding-left: 18px; }
.cbsim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #2b3242; }
@media (max-width: 480px) { .cbsim-cm-kpi { flex-basis: 40%; } .cbsim-cm-score { font-size: 38px; } .cbsim-cm-scorewrap { max-width: 100%; } }

