(function() {
    'use strict';

    class CustomBuildAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Custom Build`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD).
            this.PRICE_CEILING = 1.8;        // USD 1.8M hard ceiling
            this.PARTICIPANTS = 220;         // mid-level managers
            this.MARGIN_FLOOR = 22;          // % unit contribution-margin floor
            this.NEEDS_TARGET = 78;          // needs-alignment target for a winning bid
            this.IMPACT_TARGET = 78;         // impact-credibility target
            this.FEAS_TARGET = 70;           // feasibility target (signable in 18/90 days)

            // Concept-correct answers (the diagnosed, transfer-designed, margined, feasible bid).
            this.TRUE_GAP = `coordination`;
            this.TRUE_ROOT = `mixed`;
            this.TRUE_MEASURE = `behaviorkpi`;
            this.TRUE_FORMAT = `blended`;
            this.TRUE_TRANSFER = `projectcoach`;
            this.TRUE_FACULTY = `blend`;
            this.TRUE_LEVER = `reuse`;
            this.BEST_BID = `scaled`;         // margin held at/above floor; full = loss-leader, pricetowin = trap
            this.TRUE_DEFEND = `evidence`;
            this.TRUE_RENEWAL = `dossier`;
            this.DESIGN_SWEET = 150;          // $k design/platform sweet spot; under starves, over erases margin
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    needs: 18,
                    impact: 15,
                    feasibility: 40,
                    margin: null,            // computed at round 3 (the P&L round)
                    quality: 24,             // composite bid-quality trajectory (0-100)
                    budgetCommitted: 0,      // USD millions committed against ceiling
                    marginBelowFloor: false,
                    budgetBroken: false,
                    coverageGap: false,      // dropped 100 managers untrained
                    deadlineMissed: false,   // over-engineered past the 18-day deadline
                    noBid: false,
                    needsHistory: [18],
                    impactHistory: [15],
                    feasHistory: [40],
                    qualityHistory: [24],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `coordination`,
                    root: `mixed`,
                    measure: `behaviorkpi`,
                    rigor: 50,
                    format: `blended`,
                    transfer: `projectcoach`,
                    cohort: `staggered`,
                    modules: 6,
                    faculty: `blend`,
                    lever: `reuse`,
                    design: 200,
                    bid: `full`,
                    defend: `evidence`,
                    risk: `faculty`,
                    renewal: `dossier`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const root = document.getElementById(`rootInput`);
                const meas = document.getElementById(`measureInput`);
                const rig = document.getElementById(`rigorInput`);
                if (gap) decisions.gap = gap.value;
                if (root) decisions.root = root.value;
                if (meas) decisions.measure = meas.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                const tr = document.getElementById(`transferInput`);
                const co = document.getElementById(`cohortInput`);
                const mod = document.getElementById(`modulesInput`);
                if (fmt) decisions.format = fmt.value;
                if (tr) decisions.transfer = tr.value;
                if (co) decisions.cohort = co.value;
                if (mod) decisions.modules = parseInt(mod.value, 10);
                if (!Number.isFinite(decisions.modules) || decisions.modules < 3 || decisions.modules > 12) {
                    warn(`warn_modules_range`); return false;
                }
            } else if (round === 3) {
                const fac = document.getElementById(`facultyInput`);
                const lev = document.getElementById(`leverInput`);
                const des = document.getElementById(`designInput`);
                const bid = document.getElementById(`bidInput`);
                if (fac) decisions.faculty = fac.value;
                if (lev) decisions.lever = lev.value;
                if (des) decisions.design = parseInt(des.value, 10);
                if (bid) decisions.bid = bid.value;
                if (!Number.isFinite(decisions.design) || decisions.design < 0 || decisions.design > 500) {
                    warn(`warn_design_range`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`defendInput`);
                const ri = document.getElementById(`riskInput`);
                const re = document.getElementById(`renewalInput`);
                const cv = document.getElementById(`convictionInput`);
                if (de) decisions.defend = de.value;
                if (ri) decisions.risk = ri.value;
                if (re) decisions.renewal = re.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let needsDelta = 0, impactDelta = 0, feasDelta = 0;
            let budgetDelta = 0;          // USD millions of engagement cost committed this round
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the gap, not the request (Common Error 1).
                if (d.gap === this.TRUE_GAP) {
                    needsDelta += 16; impactDelta += 3; coachKey = `coach_r1_gap_right`;
                } else if (d.gap === `leadership`) {
                    needsDelta -= 8; impactDelta -= 4; coachKey = `coach_r1_gap_leadership`;
                } else if (d.gap === `technical`) {
                    needsDelta -= 6; impactDelta -= 3; coachKey = `coach_r1_gap_technical`;
                } else { // motivation
                    needsDelta -= 7; impactDelta -= 3; coachKey = `coach_r1_gap_motivation`;
                }

                // Root cause: only part is an education problem; flag the org-design part.
                if (d.root === this.TRUE_ROOT) {
                    needsDelta += 9; impactDelta += 3;
                    if (d.gap === this.TRUE_GAP) coachKey = `coach_r1_diag_sharp`;
                } else if (d.root === `alleducation`) {
                    needsDelta -= 6; impactDelta -= 3; coachKey = `coach_r1_alleducation`;
                } else { // allorgdesign -> decline outright, throwing away the engagement
                    needsDelta -= 4; impactDelta -= 1; coachKey = `coach_r1_allorgdesign`;
                }

                // Level 3-4 measures: a named behaviour + operational KPI is the credible commitment.
                if (d.measure === this.TRUE_MEASURE) {
                    impactDelta += 12; needsDelta += 2; coachKey = (d.gap === this.TRUE_GAP && d.root === this.TRUE_ROOT) ? `coach_r1_diag_sharp` : `coach_r1_measure_right`;
                } else if (d.measure === `reaction`) {
                    impactDelta -= 7; coachKey = `coach_r1_measure_reaction`;
                } else { // vague
                    impactDelta -= 9; coachKey = `coach_r1_measure_vague`;
                }

                // Diagnostic rigour applied to the evidence (slider; default 50 = partial only).
                if (d.rigor >= 75) { needsDelta += 6; impactDelta += 3; }
                else if (d.rigor >= 50) { needsDelta += 2; impactDelta += 1; }
                else if (d.rigor <= 25) { needsDelta -= 5; impactDelta -= 3; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.gap === this.TRUE_GAP && d.root === this.TRUE_ROOT && d.measure === this.TRUE_MEASURE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Format mix: blended balances transfer AND the ceiling. In-person blows the cap;
                // all-virtual is cheap but shallow on transfer (Common Error 2).
                // budgetDelta here = core delivery cost in USD millions.
                switch (d.format) {
                    case `blended`: needsDelta += 7; impactDelta += 7; feasDelta += 8; budgetDelta += 0.55; coachKey = `coach_r2_blended`; break;
                    case `inperson`: needsDelta += 4; impactDelta += 5; feasDelta -= 10; budgetDelta += 1.55; coachKey = `coach_r2_inperson`; break;
                    case `virtual`: needsDelta -= 4; impactDelta -= 6; feasDelta += 6; budgetDelta += 0.32; coachKey = `coach_r2_virtual`; break;
                }

                // Transfer mechanism: application projects + coaching is what earns Level 3 (Common Error 4).
                switch (d.transfer) {
                    case `projectcoach`: impactDelta += 11; needsDelta += 4; budgetDelta += 0.20; coachKey = (d.format === this.TRUE_FORMAT) ? `coach_r2_transferfit` : `coach_r2_projectcoach`; break;
                    case `assignment`: impactDelta += 2; budgetDelta += 0.05; coachKey = `coach_r2_assignment`; break;
                    case `none`: impactDelta -= 13; needsDelta -= 2; coachKey = `coach_r2_notransfer`; break;
                }

                // Cohort structure: staggered waves de-risk and let you refine (Common Error 5).
                if (d.cohort === `staggered`) { feasDelta += 7; impactDelta += 2; }
                else { feasDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_onewave` : coachKey; } // onewave

                // Modules: a focused 5-6 module journey is signable in 18 days; 9+ is over-engineering.
                if (d.modules >= 9) { feasDelta -= 12; needsDelta += 1; budgetDelta += 0.10; ds.deadlineMissed = true; coachKey = `coach_r2_overengineered`; }
                else if (d.modules >= 5 && d.modules <= 6) { feasDelta += 6; needsDelta += 2; }
                else if (d.modules <= 4) { feasDelta += 2; needsDelta -= 4; impactDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_thin` : coachKey; }
                else { feasDelta += 1; } // 7-8: borderline

                summaryKey = (d.format === this.TRUE_FORMAT && d.transfer === this.TRUE_TRANSFER && d.cohort === `staggered` && d.modules <= 8) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Faculty allocation against scarcity (make-vs-buy). Costs in USD millions.
                let facultyCost = 0;
                switch (d.faculty) {
                    case `blend`: needsDelta += 6; impactDelta += 7; feasDelta += 7; facultyCost = 0.30; coachKey = `coach_r3_blend`; break;
                    case `external`: impactDelta -= 5; feasDelta += 3; facultyCost = 0.50; coachKey = `coach_r3_external`; break; // 1.5x rates, weak dossier integration
                    case `forceinternal`: impactDelta += 1; feasDelta -= 12; facultyCost = 0.22; coachKey = `coach_r3_forceinternal`; break; // breaks Q2 commitments
                }

                // Margin-protection lever that does NOT break the diagnosis. Cost effect in USD millions.
                let leverSaving = 0;
                switch (d.lever) {
                    case `reuse`: needsDelta += 3; impactDelta += 3; feasDelta += 3; leverSaving = 0.16; coachKey = (d.faculty === this.TRUE_FACULTY) ? `coach_r3_leverfit` : `coach_r3_reuse`; break;
                    case `cutdays`: impactDelta -= 13; leverSaving = 0.22; coachKey = `coach_r3_cutdays`; break; // guts transfer -> kills Level 3
                    case `cutpax`: needsDelta -= 11; leverSaving = 0.20; ds.coverageGap = true; coachKey = `coach_r3_cutpax`; break; // leave 100 untrained
                }

                // Design & platform investment ($k -> $M). Sweet spot ~150; under starves, over erases margin.
                const designDev = Math.abs(d.design - this.DESIGN_SWEET);
                const designCostM = d.design / 1000;
                if (d.design < 75) { impactDelta -= 7; feasDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_underdesign` : coachKey; }
                else if (designDev <= 75) { impactDelta += 5; feasDelta += 2; }
                else if (d.design > 350) { impactDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_overdesign` : coachKey; }

                // The bid decision. Scaled trims delivery (lower cost, holds the floor); full bills the
                // whole ceiling as a thin loss-leader; price-to-win forces the all-external bench.
                const logisticsOverhead = 0.25; // delivery logistics + unit overhead, USD millions
                let scaledTrim = 0;
                let fullCustomCost = 0;
                let price = this.PRICE_CEILING;
                if (d.bid === `nobid`) {
                    ds.noBid = true;
                    feasDelta += 3;
                    coachKey = `coach_r3_nobid`;
                } else if (d.bid === `scaled`) {
                    scaledTrim = 0.22; // leaner delivery without breaking the diagnosis
                    needsDelta += 3; impactDelta += 3; feasDelta += 5;
                    coachKey = `coach_r3_scaled`;
                } else if (d.bid === `full`) {
                    // Full-custom delivers the whole scope at the ceiling -> richer cost, thin margin.
                    fullCustomCost = 0.30;
                    needsDelta += 2; impactDelta += 3; feasDelta += 1;
                    coachKey = `coach_r3_full`;
                } else { // pricetowin -> all-external bench, ignore the margin (Common Error 3)
                    facultyCost = 0.50; leverSaving = 0; scaledTrim = 0;
                    impactDelta -= 9; feasDelta += 1;
                    coachKey = `coach_r3_pricetowin`;
                }

                // Engagement cost committed this round (faculty + design + logistics/overhead + full-custom depth - savings).
                budgetDelta += facultyCost + designCostM + logisticsOverhead + fullCustomCost - leverSaving - scaledTrim;

                // Build the engagement P&L on the full committed cost (R2 delivery + this round).
                let margin = null;
                if (d.bid === `nobid`) {
                    margin = null; // no bid -> no margin
                } else {
                    const totalCost = ds.budgetCommitted + budgetDelta;
                    margin = Math.round(((price - totalCost) / price) * 100);
                    if (d.bid === `pricetowin`) margin = Math.min(margin, 5); // structurally sub-floor
                    margin = Math.max(-25, Math.min(40, margin));
                    ds.margin = margin;
                    ds.marginBelowFloor = margin < this.MARGIN_FLOOR;
                    if (ds.marginBelowFloor) {
                        impactDelta -= 3;
                        if (d.bid === `pricetowin`) needsDelta -= 4;
                    } else {
                        feasDelta += 3;
                    }
                }

                summaryKey = (d.faculty === this.TRUE_FACULTY && d.lever === this.TRUE_LEVER && (d.bid === `scaled` || d.bid === `full`) && !ds.coverageGap) ? `sum_r3_good`
                    : (d.bid === `pricetowin` || ds.coverageGap || d.lever === `cutdays`) ? `sum_r3_broken` : `sum_r3_weak`;
            } else if (round === 4) {
                // Defend the impact chain (Common Error 4 again, at the pitch).
                switch (d.defend) {
                    case `evidence`: impactDelta += 9; needsDelta += 4; coachKey = `coach_r4_evidence`; break;
                    case `trust`: impactDelta -= 7; coachKey = `coach_r4_trust`; break;
                    case `reframe`: impactDelta -= 10; needsDelta -= 4; coachKey = `coach_r4_reframe`; break; // retreat to confidence-only
                }

                // Name the single biggest delivery risk + mitigation. Either real risk is defensible;
                // denying risk is the trap.
                switch (d.risk) {
                    case `faculty`: feasDelta += 9; impactDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_riskfaculty` : coachKey; break;
                    case `adoption`: feasDelta += 8; impactDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_riskadoption` : coachKey; break;
                    case `none`: feasDelta -= 9; impactDelta -= 4; coachKey = `coach_r4_risknone`; break;
                }

                // Renewal logic toward the 3-year master agreement.
                switch (d.renewal) {
                    case `dossier`: needsDelta += 7; impactDelta += 6; coachKey = (d.defend === this.TRUE_DEFEND) ? `coach_r4_dossier` : coachKey; break;
                    case `discount`: needsDelta -= 5; impactDelta -= 4; coachKey = `coach_r4_discount`; break;
                    case `silent`: needsDelta -= 3; coachKey = `coach_r4_silent`; break;
                }

                // Conviction: defend a diagnosed, measurable, feasible bid over price-to-win (default 60 = partial).
                if (d.conviction >= 75) { needsDelta += 5; impactDelta += 3; feasDelta += 2; }
                else if (d.conviction >= 50) { needsDelta += 2; impactDelta += 1; }
                else if (d.conviction <= 25) { needsDelta -= 4; impactDelta -= 3; coachKey = `coach_r4_lowconviction`; }

                summaryKey = (d.defend === this.TRUE_DEFEND && d.risk !== `none` && d.renewal === this.TRUE_RENEWAL) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply KPI deltas (clamped 0-100).
            ds.needs = Math.max(0, Math.min(100, ds.needs + needsDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.feasibility = Math.max(0, Math.min(100, ds.feasibility + feasDelta));

            // Engagement cost committed against the ceiling.
            ds.budgetCommitted = Math.max(0, Math.round((ds.budgetCommitted + budgetDelta) * 100) / 100);
            if (ds.budgetCommitted > this.PRICE_CEILING + 0.001 && !ds.noBid) ds.budgetBroken = true;

            // Composite bid quality (the trajectory chart): needs + impact + feasibility,
            // with margin discipline and brand-breaking penalties. Weights leave headroom so even
            // an excellent bid lands in the low-90s, not pinned at the 100 cap.
            let quality = ds.needs * 0.33 + ds.impact * 0.33 + ds.feasibility * 0.26;
            if (ds.margin !== null && ds.margin !== undefined) {
                quality += Math.max(-12, Math.min(6, (ds.margin - this.MARGIN_FLOOR) * 0.6));
            }
            if (ds.coverageGap) quality -= 14;
            if (ds.deadlineMissed) quality -= 10;
            if (ds.budgetBroken) quality -= 12;
            if (ds.noBid) quality = Math.min(quality, 42); // a no-bid caps the bid-quality score
            ds.quality = Math.max(0, Math.min(100, Math.round(quality)));

            ds.needsHistory.push(Math.round(ds.needs));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.feasHistory.push(Math.round(ds.feasibility));
            ds.qualityHistory.push(ds.quality);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the bid-quality score where the gradebook/score resolver reads it
            // (domainState.performance.overallScore first, then a top-level score/netWorth).
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = { overallScore: _score };

            return {
                period: state.currentPeriod,
                needs: Math.round(ds.needs),
                needsDelta: Math.round(needsDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                feasibility: Math.round(ds.feasibility),
                feasDelta: Math.round(feasDelta),
                margin: ds.margin,
                quality: ds.quality,
                budgetCommitted: ds.budgetCommitted,
                marginBelowFloor: ds.marginBelowFloor,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

