        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const needs = Math.round(ds.needs);
            const impact = Math.round(ds.impact);
            const feasibility = Math.round(ds.feasibility);
            const margin = ds.margin;
            const quality = Math.round(ds.quality);

            const t = (k) => window.mySimulation.t(k);

            const needsOk = needs >= this.NEEDS_TARGET;
            const impactOk = impact >= this.IMPACT_TARGET;
            const feasOk = feasibility >= this.FEAS_TARGET;
            const marginOk = margin !== null && margin !== undefined && margin >= this.MARGIN_FLOOR;
            const broken = ds.coverageGap || ds.budgetBroken || ds.deadlineMissed;

            let performance = `Lost the Bake-Off`, performanceKey = `grade_lost`;
            if (ds.noBid) {
                if (needs >= 70 && impact >= 70) { performance = `Disciplined No-Bid`; performanceKey = `grade_nobid_disciplined`; }
                else { performance = `Walked Away Early`; performanceKey = `grade_nobid_early`; }
            } else if (needsOk && impactOk && feasOk && marginOk && !broken && quality >= 80) {
                performance = `Preferred-Provider Bid`; performanceKey = `grade_preferred`;
            } else if (needsOk && impactOk && feasOk && !broken && quality >= 70) {
                performance = `Won, Margin at Risk`; performanceKey = `grade_won_margin`;
            } else if (needsOk && impactOk && quality >= 58) {
                performance = `Credible but Fragile`; performanceKey = `grade_fragile`;
            } else if (quality >= 45) {
                performance = `Underwater Bid`; performanceKey = `grade_underwater`;
            }
            const met = (!ds.noBid && needsOk && impactOk && feasOk && !broken && quality >= 70) || (ds.noBid && needs >= 70 && impact >= 70);

            const insights = [];
            if (ds.noBid) insights.push(t(`insight_nobid`));
            else if (performance === `Preferred-Provider Bid`) insights.push(t(`insight_preferred`));
            else if (!needsOk) insights.push(t(`insight_needs`));
            else if (!impactOk) insights.push(t(`insight_impact`));

            if (ds.marginBelowFloor && !ds.noBid) insights.push(t(`insight_margin`));
            if (ds.coverageGap) insights.push(t(`insight_coverage`));
            if (ds.budgetBroken) insights.push(t(`insight_budget`));
            if (ds.deadlineMissed) insights.push(t(`insight_deadline`));
            if (needsOk && impactOk && feasOk && marginOk && !broken) insights.push(t(`insight_won`));

            return {
                needs: needs,
                impact: impact,
                feasibility: feasibility,
                margin: margin,
                quality: quality,
                marginOk: marginOk,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.quality != null ? s.quality : (s.overallScore != null ? s.overallScore : 0));
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || ``);
            const badge = s.met
                ? `<span class="cbsim-cm-badge cbsim-cm-badge-ok">${t(`cm_targets_met`)}</span>`
                : `<span class="cbsim-cm-badge cbsim-cm-badge-miss">${t(`cm_targets_missed`)}</span>`;
            const fmt = (v, suf) => ((v != null && v !== undefined) ? Math.round(v) + (suf || ``) : `—`);
            const kpi = (k, v, suf) => `<div class="cbsim-cm-kpi"><div class="cbsim-cm-kpi-val">${fmt(v, suf)}</div><div class="cbsim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="cbsim-cm-insights"><div class="cbsim-cm-ins-h">${t(`cm_insights`)}</div><ul>${ins.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;
            return `
                <div class="cbsim-cm">
                    <div class="cbsim-cm-title">${t(`cm_title`)}</div>
                    <div class="cbsim-cm-scorewrap">
                        <div class="cbsim-cm-score">${score}<span class="cbsim-cm-score-max">/100</span></div>
                        <div class="cbsim-cm-grade">${grade}</div>
                        <div class="cbsim-cm-badges">${badge}</div>
