                    <div class="cbsim-cm-kpis">
                        ${kpi(`cm_kpi_needs`, s.needs, ``)}
                        ${kpi(`cm_kpi_impact`, s.impact, ``)}
                        ${kpi(`cm_kpi_feas`, s.feasibility, ``)}
                        ${kpi(`cm_kpi_margin`, s.margin, `%`)}
                    </div>
                    ${insHtml}
                </div>`;
