        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            const t = (k) => window.mySimulation.t(k);
            if (ds.budgetBroken) return t(`hint_budget`);
            if (ds.coverageGap) return t(`hint_coverage`);
            if (ds.marginBelowFloor) return t(`hint_margin`);
            if (state.currentPeriod >= 1 && ds.needs < 45) return t(`hint_needs`);
            if (state.currentPeriod >= 2 && ds.impact < 45) return t(`hint_impact`);
            if (state.currentPeriod >= 2 && ds.feasibility < 45) return t(`hint_feasibility`);
            if (ds.needs >= this.NEEDS_TARGET && ds.impact >= this.IMPACT_TARGET) return t(`hint_strong`);
            return null;
        }

